package com.coraline.postgame;

import java.nio.charset.StandardCharsets;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.*;
import net.minecraft.server.level.*;

/** Discovered native locations feed missions; only physical objective callbacks
 * write regional completion evidence. Dialogue cannot manufacture a victory. */
public final class PostgameQuests {
    enum Mission {
        TOWER("coraline","navigation",InfiniteStructurePlan.Family.MIRROR_TOWER),
        FACTORY("coraline","investigation",InfiniteStructurePlan.Family.CLOCKWORK_FACTORY),
        CARNIVAL("coraline","performance",InfiniteStructurePlan.Family.ENDLESS_CARNIVAL),
        ORPHANAGE("coraline","rescue",InfiniteStructurePlan.Family.ABANDONED_ORPHANAGE),
        THEATRE("coraline","performance",InfiniteStructurePlan.Family.GRAND_THEATRE),
        SANCTUARY("coraline","defense",InfiniteStructurePlan.Family.RESISTANCE_SANCTUARY),
        SEAM("wybie","alignment",InfiniteStructurePlan.Family.DIMENSIONAL_SEAM),
        DRILL("wybie","machinery",InfiniteStructurePlan.Family.RIFT_DRILL_CENTER),
        BOUNDARY("wybie","defense",InfiniteStructurePlan.Family.ANCIENT_BOUNDARY_SHRINE),
        OBSERVATORY("wybie","observation",InfiniteStructurePlan.Family.FORGOTTEN_OBSERVATORY),
        HEART_LOCATION("wybie","exploration",InfiniteStructurePlan.Family.ENTITY_HEART_CHAMBER),
        HEART("wybie","containment",InfiniteStructurePlan.Family.ENTITY_HEART_CHAMBER);
        final String giver,category;final InfiniteStructurePlan.Family family;
        Mission(String giver,String category,InfiniteStructurePlan.Family family){this.giver=giver;this.category=category;this.family=family;}
    }
    private static Boolean closedInWorld(ServerLevel level,InfiniteStructurePlan.Plan plan){BlockPos at=switch(plan.family()){case GRAND_THEATRE->PerformanceLayout.core(plan);case ENDLESS_CARNIVAL->CarnivalLayout.core(plan);case ABANDONED_ORPHANAGE->OrphanageLayout.register(plan,3);case RESISTANCE_SANCTUARY,ANCIENT_BOUNDARY_SHRINE,ENTITY_HEART_CHAMBER->BoundaryDefenseLayout.core(plan);case DIMENSIONAL_SEAM->SeamLayout.parts(plan).get(0);case FORGOTTEN_OBSERVATORY->ObservatoryLayout.core(plan);case RIFT_DRILL_CENTER->RiftMachineLayout.parts(plan).get(0).at();case CLOCKWORK_FACTORY->FactoryLayout.part(plan,0);default->null;};if(at!=null&&!level.hasChunkAt(at))return null;net.minecraft.world.level.block.entity.BlockEntity node;switch(plan.family()){
        case GRAND_THEATRE:node=level.getBlockEntity(PerformanceLayout.core(plan));return node instanceof PerformanceEntity n&&n.questAvailable()?n.complete():null;
        case ENDLESS_CARNIVAL:node=level.getBlockEntity(CarnivalLayout.core(plan));return node instanceof CarnivalEntity n&&n.questAvailable()?n.complete():null;
        case ABANDONED_ORPHANAGE:node=level.getBlockEntity(OrphanageLayout.register(plan,3));return node instanceof OrphanageEntity n&&n.questAvailable()?n.complete():null;
        case RESISTANCE_SANCTUARY,ANCIENT_BOUNDARY_SHRINE,ENTITY_HEART_CHAMBER:node=level.getBlockEntity(BoundaryDefenseLayout.core(plan));return node instanceof BoundaryDefenseEntity n&&n.authentic()?n.complete():null;
        case DIMENSIONAL_SEAM:node=level.getBlockEntity(SeamLayout.parts(plan).get(0));return node instanceof SeamAnchorEntity n&&n.authentic()?n.closed():null;
        case FORGOTTEN_OBSERVATORY:node=level.getBlockEntity(ObservatoryLayout.core(plan));return node instanceof ObservatoryEntity n&&n.authentic()?n.complete():null;
        case RIFT_DRILL_CENTER:node=level.getBlockEntity(RiftMachineLayout.parts(plan).get(0).at());return node instanceof RiftMachineEntity n&&n.authentic()?n.disabled():null;
        case CLOCKWORK_FACTORY:var cache=factoryCache(plan);if(cache==null||!level.hasChunkAt(cache))return null;node=level.getBlockEntity(cache);var machine=FactoryLayout.core(level,plan);return node instanceof SiteCacheBlockEntity n&&n.authentic()&&machine!=null?n.factoryInvestigated()&&machine.complete():null;
        default:return false;}}
    private static BlockPos factoryCache(InfiniteStructurePlan.Plan plan){for(int i=0;i<plan.modules().size();i++)if(plan.modules().get(i).role()==InfiniteStructurePlan.Role.CONTROL)return SiteCacheReceipt.position(plan,i);return null;}
    static void factoryCompletedIfReady(ServerPlayer player,InfiniteStructurePlan.Plan plan){var core=FactoryLayout.core(player.level(),plan);var at=FactoryLayout.archive(plan);if(core!=null&&core.complete()&&player.level().hasChunkAt(at)&&player.level().getBlockEntity(at) instanceof SiteCacheBlockEntity cache&&cache.authentic()&&cache.factoryInvestigated())completed(player,plan);}
    private static PostgameQuestState state(ServerPlayer p){return InfiniteWorldData.get(p.server).generation().map(id->PostgameQuestState.get(p.server,id,p.getUUID())).filter(PostgameQuestState::ready).orElse(null);}
    private static void say(ServerPlayer p,String key,Object... args){p.sendSystemMessage(Component.translatable("message.coraline.quest_"+key,args));}
    static boolean eligible(ServerPlayer p){return !TrueHeartBattle.recoveryPending(p)&&p.isAlive()&&!p.isCreative()&&!p.isSpectator()&&InfiniteWorldData.get(p.server).accessible();}
    private static CompoundTag location(InfiniteStructurePlan.Plan plan,long now){var n=new CompoundTag();n.putUUID("Site",plan.site());n.putString("Family",plan.family().name());n.putInt("AnchorX",plan.x());n.putInt("AnchorZ",plan.z());n.putInt("Y",plan.y());n.putLong("Seen",now);n.putString("Biome",plan.biome().name());return n;}
    static void discover(ServerPlayer p,InfiniteStructurePlan.Plan plan){if(!eligible(p)||!InfiniteWorldData.get(p.server).matchesGeneration(plan.generation()))return;var d=state(p);if(d==null)return;var closed=closedInWorld(p.serverLevel(),plan);if(closed==null)return;if(!closed)InfiniteDiscoveryRegion.get(p.serverLevel(),plan.generation(),plan.x()>>4,plan.z()>>4).participate(plan,p.getUUID(),p.server.overworld().getGameTime());if(closed){var region=InfiniteDiscoveryRegion.get(p.serverLevel(),plan.generation(),plan.x()>>4,plan.z()>>4);if(region.finished(plan.site())==null)region.finish(plan,new UUID(0,0),p.server.overworld().getGameTime());}if(MirrorTowerLayout.reachedSummit(p,plan))completed(p,plan);var candidates=d.raw.getList("Candidates",Tag.TAG_COMPOUND);if(candidates.stream().noneMatch(tag->((CompoundTag)tag).getUUID("Site").equals(plan.site()))){if(candidates.size()>=16)candidates.remove(0);candidates.add(location(plan,p.server.overworld().getGameTime()));d.setDirty();}if(plan.family()==InfiniteStructurePlan.Family.SOUL_GLASS_MINE&&!d.raw.contains("Mine")){d.raw.put("Mine",location(plan,p.server.overworld().getGameTime()));d.setDirty();}var active=d.raw.getCompound("Wybie");if(d.raw.getInt("Research")==5&&active.hasUUID("Site")&&active.getUUID("Site").equals(plan.site())&&active.getString("Mission").equals(Mission.HEART_LOCATION.name())&&!active.contains("Visited")){active.putLong("Visited",p.server.overworld().getGameTime());d.setDirty();}}
    /** Called only at the actual first successful native objective transition. */
    static void completed(ServerPlayer p,InfiniteStructurePlan.Plan plan){if(p==null||!eligible(p)||!(p.serverLevel().getChunkSource().getGenerator() instanceof InfiniteChunkGenerator generator)||!generator.structureGeneration().id().equals(plan.generation())||generator.structureGeneration().seed()!=plan.seed()||!InfiniteWorldData.get(p.server).matchesGeneration(plan.generation()))return;InfiniteDiscoveryRegion.get(p.serverLevel(),plan.generation(),plan.x()>>4,plan.z()>>4).finish(plan,p.getUUID(),p.server.overworld().getGameTime());}
    private static InfiniteDiscoveryRegion shard(ServerPlayer p,PostgameQuestState d,CompoundTag location){return InfiniteDiscoveryRegion.get(p.serverLevel(),d.generation,location.getInt("AnchorX")>>4,location.getInt("AnchorZ")>>4);}
    private static String key(String giver){return giver.equals("coraline")?"Coraline":"Wybie";}
    private static Mission research(int stage){return switch(stage){case 0->Mission.SEAM;case 1->Mission.DRILL;case 2->Mission.BOUNDARY;case 4->Mission.OBSERVATORY;case 5->Mission.HEART_LOCATION;case 6->Mission.HEART;default->null;};}
    private static boolean completed(ServerPlayer p,PostgameQuestState d,CompoundTag active){Mission mission;try{mission=Mission.valueOf(active.getString("Mission"));}catch(IllegalArgumentException unknown){return false;}if(mission==Mission.HEART_LOCATION)return active.contains("Visited",Tag.TAG_LONG)&&active.getLong("Visited")>=active.getLong("Assigned");var proof=shard(p,d,active).finished(active.getUUID("Site"));return proof!=null&&InfiniteDiscoveryRegion.credited(proof,p.getUUID())&&proof.getString("Family").equals(mission.family.name())&&proof.getLong("At")>=active.getLong("Assigned");}
    private static void offer(ServerPlayer p,PostgameQuestState d,String giver,Mission required){CompoundTag best=null;Mission chosen=null;int highest=Integer.MIN_VALUE;var recent=d.raw.getList("Recent",Tag.TAG_STRING);for(var tag:d.raw.getList("Candidates",Tag.TAG_COMPOUND)){var candidate=(CompoundTag)tag;var region=shard(p,d,candidate);if(!region.usable())continue;for(var mission:Mission.values()){if(!mission.giver.equals(giver)||required==null&&mission==Mission.HEART_LOCATION||required!=null&&mission!=required||!candidate.getString("Family").equals(mission.family.name()))continue;if(mission!=Mission.HEART_LOCATION&&region.finished(candidate.getUUID("Site"))!=null)continue;int score=100+p.getRandom().nextInt(20)-Math.max(0,mission.family.difficulty-2)*3;if(BreachWorldData.get(p.server).view().millionths()>=1500000&&(mission.category.equals("containment")||mission.category.equals("defense")))score+=15;for(var biome:d.raw.getList("RecentBiomes",Tag.TAG_STRING))if(biome.getAsString().equals(candidate.getString("Biome")))score-=8;for(var old:recent)if(old.getAsString().equals(mission.category))score-=40;if(score>highest){highest=score;best=candidate;chosen=mission;}}}if(best==null){say(p,"explore",Component.translatable("quest.coraline."+(required==null?"new_mysteries":required.name().toLowerCase(Locale.ROOT))));return;}var active=best.copy();active.putString("Mission",chosen.name());active.putInt("RewardVersion",1);active.putLong("Assigned",p.server.overworld().getGameTime());active.putUUID("Claim",UUID.randomUUID());d.raw.put(key(giver),active);if(d.commit(p.server))status(p,active);}
    private static void status(ServerPlayer p,CompoundTag active){say(p,"destination",Component.translatable("quest.coraline."+active.getString("Mission").toLowerCase(Locale.ROOT)),active.getInt("AnchorX"),active.getInt("Y"),active.getInt("AnchorZ"));say(p,"goal_"+active.getString("Mission").toLowerCase(Locale.ROOT));say(p,"rewards",QuestWallet.description(active));}
    static void coraline(ServerPlayer p){interact(p,"coraline");}
    static void wybie(ServerPlayer p){interact(p,"wybie");}
    private static void interact(ServerPlayer p,String giver){if(!eligible(p)||p.containerMenu!=p.inventoryMenu)return;var d=state(p);if(d==null){say(p,"save_paused");return;}long now=p.server.overworld().getGameTime();if(d.raw.contains("NextTalk",Tag.TAG_LONG)&&now<d.raw.getLong("NextTalk"))return;d.raw.putLong("NextTalk",now+20);d.setDirty();if(giver.equals("coraline")&&now>=d.raw.getLong("BreachCommentAfter")){int breach=BreachWorldData.get(p.server).view().millionths();say(p,breach>=2000000?"world_avatar":breach>=1500000?"world_spreading":breach>=1000000?"world_raids":"world_quiet");d.raw.putLong("BreachCommentAfter",now+600);d.setDirty();}int stage=d.raw.getInt("Research");if(giver.equals("wybie")){if(stage==3){components(p,d);return;}if(stage>=7&&!d.raw.contains("Wybie")&&!p.isShiftKeyDown()){warning(p,d);return;}}
        String key=key(giver);if(giver.equals("wybie")&&stage==6&&!d.raw.contains(key)&&d.raw.contains("ResearchHeart",Tag.TAG_COMPOUND)){var old=d.raw.getCompound("ResearchHeart");var proof=shard(p,d,old).finished(old.getUUID("Site"));if(proof!=null&&InfiniteDiscoveryRegion.credited(proof,p.getUUID())&&proof.getLong("At")>=old.getLong("Assigned")){var next=old.copy();next.putString("Mission",Mission.HEART.name());next.putUUID("Claim",UUID.randomUUID());d.raw.put(key,next);if(!d.commit(p.server))return;}}
        if(d.raw.contains(key,Tag.TAG_COMPOUND)){var active=d.raw.getCompound(key);if(completed(p,d,active)){claim(p,d,giver,active);return;}if(p.isShiftKeyDown()){d.raw.remove(key);if(d.commit(p.server))say(p,"abandoned");return;}var proof=shard(p,d,active).finished(active.getUUID("Site"));if(proof!=null&&!active.getString("Mission").equals(Mission.HEART_LOCATION.name())){d.raw.remove(key);if(d.commit(p.server))say(p,"finished_elsewhere");return;}status(p,active);return;}offer(p,d,giver,giver.equals("wybie")&&stage<7?research(stage):null);
    }
    private static void claim(ServerPlayer p,PostgameQuestState d,String giver,CompoundTag active){if(!active.hasUUID("Claim"))return;var token=active.getUUID("Claim");boolean cor=giver.equals("coraline");var paid=MirrorTransactions.questRewardStatus(p,token,cor);if(paid==MirrorTransactions.Result.FROZEN){say(p,"save_paused");return;}if(paid!=MirrorTransactions.Result.COMMITTED){var plan=QuestWallet.reward(p,active);if(plan==null){say(p,"reward_space");return;}if(MirrorTransactions.commitQuest(p,plan,token,cor)!=MirrorTransactions.Result.COMMITTED){say(p,"save_paused");return;}}
        var receipt=active.copy();receipt.putUUID("Objective",UUID.nameUUIDFromBytes((p.getUUID()+":"+giver+":"+active.getString("Mission")+":"+active.getUUID("Site")).getBytes(StandardCharsets.UTF_8)));receipt.putString("Giver",giver);d.raw.put("HandedIn",receipt);if(!d.commit(p.server))return;var realm=p.server.getLevel(InfiniteRealm.key(d.generation));if(realm!=null)BreachWorldData.get(p.server).resolveQuest(realm,p);var recent=d.raw.getList("Recent",Tag.TAG_STRING);if(recent.size()>=6)recent.remove(0);recent.add(StringTag.valueOf(Mission.valueOf(active.getString("Mission")).category));if(!d.raw.contains("RecentBiomes"))d.raw.put("RecentBiomes",new ListTag());var biomes=d.raw.getList("RecentBiomes",Tag.TAG_STRING);if(biomes.size()>=6)biomes.remove(0);biomes.add(StringTag.valueOf(active.getString("Biome")));if(!cor&&d.raw.getInt("Research")<7){var proof=active.copy();proof.putString("Kind",active.getString("Mission"));history(d,proof);if(active.getString("Mission").equals(Mission.HEART_LOCATION.name()))d.raw.put("ResearchHeart",active.copy());d.raw.putInt("Research",d.raw.getInt("Research")+1);}d.raw.remove(key(giver));if(d.commit(p.server))say(p,"completed",Component.translatable("quest.coraline."+active.getString("Mission").toLowerCase(Locale.ROOT)));
    }
    private static void components(ServerPlayer p,PostgameQuestState d){if(!d.raw.contains("Mine",Tag.TAG_COMPOUND)){say(p,"find_mine");return;}if(!d.raw.hasUUID("Payment")){d.raw.putUUID("Payment",UUID.randomUUID());if(!d.commit(p.server))return;}var token=d.raw.getUUID("Payment");var result=MirrorTransactions.researchPayment(p,token);if(result==MirrorTransactions.Result.FROZEN){say(p,"save_paused");return;}if(result!=MirrorTransactions.Result.COMMITTED){var plan=QuestWallet.donation(p);if(plan==null){say(p,"components");return;}if(MirrorTransactions.commitResearch(p,plan,token)!=MirrorTransactions.Result.COMMITTED){say(p,"save_paused");return;}}var proof=d.raw.getCompound("Mine").copy();proof.putString("Kind","COMPONENTS");proof.putUUID("Payment",token);history(d,proof);d.raw.putInt("Research",4);if(d.commit(p.server))say(p,"components_received");}
    private static void history(PostgameQuestState d,CompoundTag proof){if(!d.raw.contains("ResearchHistory"))d.raw.put("ResearchHistory",new ListTag());d.raw.getList("ResearchHistory",Tag.TAG_COMPOUND).add(proof);}
    private static void warning(ServerPlayer p,PostgameQuestState d){if(d.raw.getInt("Research")==8){say(p,"instructions");TrueHeartBattle.offer(p);return;}if(!d.raw.hasUUID("Warning")){d.raw.putUUID("Warning",UUID.randomUUID());if(!d.commit(p.server))return;}say(p,"warning");var nonce=d.raw.getUUID("Warning").toString();p.sendSystemMessage(Component.translatable("message.coraline.quest_how").withStyle(s->s.withClickEvent(new ClickEvent(ClickEvent.Action.RUN_COMMAND,"/coraline final_research how "+nonce))).append(Component.literal("   ")).append(Component.translatable("message.coraline.quest_later").withStyle(s->s.withClickEvent(new ClickEvent(ClickEvent.Action.RUN_COMMAND,"/coraline final_research later "+nonce)))));}
    static boolean decide(ServerPlayer p,UUID token,boolean how){if(!eligible(p))return false;var d=state(p);if(d==null||!WybieRescue.nearReturnedWybie(p)||d.raw.getInt("Research")!=7||!d.raw.hasUUID("Warning")||!d.raw.getUUID("Warning").equals(token))return false;if(!how){say(p,"keep_exploring");return true;}var proof=new CompoundTag();proof.putString("Kind","WARNING");proof.putUUID("Warning",token);history(d,proof);d.raw.putInt("Research",8);if(d.commit(p.server))say(p,"instructions");return true;}
    static CompoundTag handedIn(ServerPlayer p){var d=state(p);if(d==null||!d.raw.contains("HandedIn",Tag.TAG_COMPOUND))return null;var n=d.raw.getCompound("HandedIn");if(!n.hasUUID("Claim")||!n.hasUUID("Objective")||!completed(p,d,n)||MirrorTransactions.questRewardStatus(p,n.getUUID("Claim"),n.getString("Giver").equals("coraline"))!=MirrorTransactions.Result.COMMITTED)return null;return n;}
    static boolean finalKnowledge(ServerPlayer p){var d=state(p);return d!=null&&d.raw.getInt("Research")==8;}
    private PostgameQuests(){}
}
